int chk(ll s, ll e){
    if(e == s)return 0;
    if(e == s+1)return 1;
    if(e & 1){
        if(s & 1)return 0;
        return 1;
    }
    if(s <= e/4)
        return chk(s, e/4);
    if(s > (e/4)*2)return ((e-s)&1);
    else return 1;
}

int lck(ll s, ll e){
    if(s*2 > e)return 1;
    int w = e/2 + 3;
    while(w*2 > e)w--;
    return chk(s, w);
}

